const exp=require("./tests/expected.json");
let v=exp.input; const out=[v];
const A=v=>(v+Math.floor(v/3))%997;
const B=(v,i)=>v^((i*7)%64);
const C=(v,i)=>(v*3-i)%991;
const D=v=>(v*2+1)%1000;
for(let i=1;i<=32;i++){
  const k=(i-1)%4;
  v = k===0?A(v):k===1?B(v,i):k===2?C(v,i):D(v);
  out.push(v);
}
console.log(JSON.stringify(out));
console.log(JSON.stringify(out)===JSON.stringify(exp.stages.map((x,j)=>x)) ? "MATCH-check":"");
'

